"use client";

import Link from "next/link";
import { useEffect, useId, useRef, useState } from "react";

import { MegaMenuTile } from "./MegaMenuTile";
import { useCart } from "./cart-context";
import { useSearchModal } from "./search-context";
import { BRAND } from "@/lib/brand";
import { NAVIGATION, type NavPanel } from "@/lib/data/navigation";

/**
 * Navigation Header — exact match to original tilfi.com.
 *
 * Structure (per live site measurement):
 * - Position: static (scrolls away with page)
 * - Height: 141px desktop (centered wordmark + split nav)
 * - Single row: centered Cardo wordmark + 6 nav triggers
 * - Interaction: CLICK-TO-OPEN only (no hover intent)
 * - Mega panels: 4-column grid (3 link columns + 1 image tile)
 * - Active state: gold #ae7922 bottom border + text color
 */

const CLOSE_DELAY_MS = 300;
const GOLD = "#ae7922";

export function SiteHeader() {
  const [openPanel, setOpenPanel] = useState<string | null>(null);
  const [mobileOpen, setMobileOpen] = useState(false);
  const closeTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const navRef = useRef<HTMLDivElement>(null);
  const panelId = useId();

  const { itemCount, open: openCart } = useCart();
  const { open: openSearch } = useSearchModal();

  useEffect(() => {
    return () => {
      clearTimeout(closeTimer.current);
    };
  }, []);

  // Escape closes the panel and returns focus to the trigger that opened it.
  useEffect(() => {
    if (!openPanel && !mobileOpen) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      if (openPanel) {
        document.getElementById(`${panelId}-trigger-${openPanel}`)?.focus();
        setOpenPanel(null);
      }
      setMobileOpen(false);
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [openPanel, mobileOpen, panelId]);

  // Outside click closes the panel.
  useEffect(() => {
    if (!openPanel) return;
    const onPointerDown = (event: PointerEvent) => {
      if (!navRef.current?.contains(event.target as Node)) setOpenPanel(null);
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [openPanel]);

  const scheduleClose = () => {
    closeTimer.current = setTimeout(() => setOpenPanel(null), CLOSE_DELAY_MS);
  };

  return (
    <header
      ref={navRef}
      className="relative z-50 bg-bg border-b border-rule"
      style={{ height: "141px" }}
    >
      {/* Single Row: Centered Wordmark + 6 Nav Triggers */}
      <div className="hidden lg:flex items-center justify-center h-[141px] w-full">
        <nav aria-label="Primary navigation" className="w-full max-w-[1360px] mx-auto px-8 xl:px-12">
          <ul className="flex justify-center items-center gap-8 xl:gap-12 w-full h-full">
            {NAVIGATION.map((panel) => (
              <li key={panel.id} className="h-full flex items-center">
                <button
                  type="button"
                  id={`${panelId}-trigger-${panel.id}`}
                  aria-expanded={openPanel === panel.id}
                  aria-controls={`${panelId}-panel-${panel.id}`}
                  className={`
                    eyebrow text-[12.5px] xl:text-[13.5px] tracking-[0.16em] uppercase font-medium
                    transition-colors h-full flex items-center border-b-2 cursor-pointer
                    ${openPanel === panel.id
                      ? `text-[${GOLD}] border-[${GOLD}]`
                      : "text-ink border-transparent hover:text-[${GOLD}] hover:border-transparent"
                    }
                  `}
                  onClick={() => setOpenPanel((current) => (current === panel.id ? null : panel.id))}
                  onFocus={() => setOpenPanel(panel.id)}
                >
                  {panel.label}
                </button>
              </li>
            ))}
          </ul>
        </nav>
      </div>

      {/* Mega Panels */}
      {NAVIGATION.map((panel) => (
        <MegaPanel
          key={panel.id}
          panel={panel}
          id={`${panelId}-panel-${panel.id}`}
          open={openPanel === panel.id}
          onMouseEnter={() => clearTimeout(closeTimer.current)}
          onClose={() => setOpenPanel(null)}
        />
      ))}

      {/* Mobile Header */}
      <div className="flex lg:hidden items-center justify-between px-4 h-[77px] bg-bg border-b border-rule">
        <button
          type="button"
          onClick={() => setMobileOpen((prev) => !prev)}
          className="p-1.5 text-ink hover:text-ink-muted transition-colors"
          aria-label={mobileOpen ? "Close navigation" : "Open navigation"}
          aria-expanded={mobileOpen}
        >
          {mobileOpen ? (
            <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75">
              <line x1="18" y1="6" x2="6" y2="18" />
              <line x1="6" y1="6" x2="18" y2="18" />
            </svg>
          ) : (
            <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75">
              <line x1="3" y1="6" x2="21" y2="6" />
              <line x1="3" y1="12" x2="21" y2="12" />
              <line x1="3" y1="18" x2="21" y2="18" />
            </svg>
          )}
        </button>

        <Link href="/" className="text-center" aria-label={`${BRAND.name} home`}>
          <span className="font-display text-xl tracking-[0.2em] uppercase text-ink font-normal">
            {BRAND.name}
          </span>
        </Link>

        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={openSearch}
            className="p-1.5 text-ink hover:text-ink-muted transition-colors"
            aria-label="Search"
          >
            <svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75">
              <circle cx="11" cy="11" r="8" />
              <line x1="21" y1="21" x2="16.65" y2="16.65" />
            </svg>
          </button>
          <Link
            href="/cart"
            className="p-1.5 text-ink hover:text-ink-muted transition-colors relative block"
            aria-label={`Cart${itemCount > 0 ? `, ${itemCount} items` : ""}`}
          >
            <svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75">
              <path d="M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z" />
              <line x1="3" y1="6" x2="21" y2="6" />
              <path d="M16 10a4 4 0 0 1-8 0" />
            </svg>
            {itemCount > 0 && (
              <span className="absolute -top-0.5 -right-0.5 bg-ink text-bg text-[9px] w-4 h-4 rounded-full flex items-center justify-center font-mono">
                {itemCount}
              </span>
            )}
          </Link>
        </div>
      </div>

      {mobileOpen ? (
        <MobileNav id={`${panelId}-mobile`} onNavigate={() => setMobileOpen(false)} />
      ) : null}
    </header>
  );
}

function MegaPanel({
  panel,
  id,
  open,
  onMouseEnter,
  onClose,
}: {
  panel: NavPanel;
  id: string;
  open: boolean;
  onMouseEnter: () => void;
  onClose: () => void;
}) {
  const panelRef = useRef<HTMLDivElement>(null);

  // Keyboard navigation within mega panel
  useEffect(() => {
    if (!open) return;
    const onKeyDown = (event: KeyboardEvent) => {
      const focusable = panelRef.current?.querySelectorAll<HTMLElement>(
        'a[href], button:not([disabled]), [tabindex]:not([tabindex="-1"])',
      );
      if (!focusable || focusable.length === 0) return;

      const currentIndex = Array.from(focusable).findIndex(
        (el) => el === document.activeElement,
      );
      if (currentIndex === -1) return;

      let nextIndex = currentIndex;
      if (event.key === "ArrowRight") {
        nextIndex = (currentIndex + 1) % focusable.length;
        event.preventDefault();
      } else if (event.key === "ArrowLeft") {
        nextIndex = (currentIndex - 1 + focusable.length) % focusable.length;
        event.preventDefault();
      } else {
        return;
      }
      focusable[nextIndex]?.focus();
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [open, panel]);

  if (!open) return null;

  return (
    <div
      ref={panelRef}
      id={id}
      aria-label={panel.label}
      onMouseEnter={onMouseEnter}
      className="absolute inset-x-0 top-full border-t border-b border-rule bg-white z-40"
    >
      <div className="max-w-[1360px] mx-auto px-8 xl:px-12 grid grid-cols-4 gap-8 py-8">
        {panel.columns.map((column) => (
          <div key={column.heading} className="min-w-0">
            <h2 className="eyebrow text-xs uppercase tracking-[0.14em] font-semibold text-ink mb-3 pb-1 border-b border-rule/60">
              {column.heading}
            </h2>
            <ul className="space-y-2">
              {column.links.map((link) => (
                <li key={link.href + link.label}>
                  <Link
                    href={link.href}
                    onClick={onClose}
                    className={`text-[13px] text-ink/85 hover:text-[${GOLD}] transition-colors py-0.5 block ${
                      link.emphasis ? "font-semibold text-ink hover:text-[${GOLD}]" : ""
                    }`}
                  >
                    {link.label}
                  </Link>
                </li>
              ))}
            </ul>
          </div>
        ))}

        {/* Merchandised slots — editorial choices */}
        <div className="col-start-4 grid gap-4">
          {panel.tiles.map((tile) => (
            <MegaMenuTile
              key={tile.href}
              label={tile.label}
              tone={tile.tone}
              src={tile.src}
              alt={tile.label}
              href={tile.href}
              onClose={onClose}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

function MobileNav({ id, onNavigate }: { id: string; onNavigate: () => void }) {
  return (
    <div id={id} className="border-t border-rule bg-bg lg:hidden">
      <nav aria-label="Primary navigation" className="wrap-wide py-6">
        {NAVIGATION.map((panel) => (
          <details key={panel.id} className="border-b border-rule py-3">
            <summary className="eyebrow cursor-pointer text-ink">{panel.label}</summary>
            <div className="mt-4 space-y-5 pb-2">
              {panel.columns.map((column) => (
                <div key={column.heading}>
                  <h2 className="eyebrow mb-2 text-ink-muted">{column.heading}</h2>
                  <ul className="space-y-2">
                    {column.links.map((link) => (
                      <li key={link.href + link.label}>
                        <Link
                          href={link.href}
                          onClick={onNavigate}
                          className="text-caption text-ink-body"
                        >
                          {link.label}
                        </Link>
                      </li>
                    ))}
                  </ul>
                </div>
              ))}
            </div>
          </details>
        ))}
        <Link href="/search" onClick={onNavigate} className="eyebrow mt-5 block text-ink">
          Search
        </Link>
      </nav>
    </div>
  );
}